public function addLink(string $href, string $rel, string $hreflang = ''): void {
		$key = $hreflang !== '' ? $href . '|' . $hreflang : $href;

		$this->links[$key] = [
			'href'     => $href,
			'rel'      => $rel,
			'hreflang' => $hreflang
		];
	}

	/**
	 * @param string $href
	 * @param string $hreflang
	 *
	 * @return void
	 */
	public function addHreflang(string $href, string $hreflang): void {
		$this->addLink($href, 'alternate', $hreflang);
	}
